//   FROM (SELECT TOP 5 a FROM t ORDER BY a DESC
//         UNION ALL SELECT TOP 5 a FROM u ORDER BY a DESC) AS d
// An ORDER BY after a last branch with TOP is that branch's (dynamic
// precedence); after a last branch without TOP, or when OFFSET/FETCH
// follows it, it is the union's, as at top level, where `set_operation`
// is unchanged. OFFSET/FETCH is part of the ORDER BY clause and TOP and
